  "code": "class TheObject:\n    def __init__(self, pType, pAmount):\n        self.ObjectType = pType      # string: \"Money\" or \"Experience\"\n        self.Amount = pAmount        # integer\n\nclass Path:\n    def __init__(self, pNumberSpaces):\n        self.BoardArray = []         # 100 objects of type TheObject\n        self.NumberSpaces = pNumberSpaces   # integer\n        for Index in range(100):\n            self.BoardArray.append(TheObject(\"\", -1))   # an empty object\n\n    def GetNumberSpaces(self):\n        return self.NumberSpaces\n\n    def InitialiseData(self, TheArray):\n        if len(TheArray) > self.NumberSpaces:\n            return False\n        for Index in range(len(TheArray)):\n            self.BoardArray[Index] = TheArray[Index]\n        return True\n\n    def ReturnPath(self):\n        Result = \"\"\n        for Item in self.BoardArray:\n            if Item.ObjectType != \"\":            # ignore the empty objects\n                Result = Result + Item.ObjectType + \"-\" + str(Item.Amount) + \" \"\n        return Result.strip()\n\n    def GetPathObject(self, TheIndex):\n        return self.BoardArray[TheIndex]\n\nArrayOfObjects = [TheObject(\"Money\", 50), TheObject(\"Experience\", 100), TheObject(\"Money\", 200),\n                  TheObject(\"Money\", 20), TheObject(\"Experience\", 30)]\nPath1 = Path(5)\nPath1.InitialiseData(ArrayOfObjects)\nprint(Path1.ReturnPath())\nprint(Path1.InitialiseData(ArrayOfObjects * 2))     # 10 objects for 5 spaces: returns False",
