  "code": "class Character:\n    def __init__(self, pName, pColour, pStrength, pFly, pInvisible):\n        self.__CharacterName = pName\n        self.__Colour = pColour\n        self.__SuperStrength = pStrength\n        self.__Fly = pFly\n        self.__Invisible = pInvisible\n\n    def GetCharacterName(self):\n        return self.__CharacterName\n    def GetColour(self):\n        return self.__Colour\n    def GetSuperStrength(self):\n        return self.__SuperStrength\n    def GetFly(self):\n        return self.__Fly\n    def GetInvisible(self):\n        return self.__Invisible\n\ndef ReadData():\n    AllCharacters = []                       # local array\n    try:\n        TheFile = open(\"Characters.txt\", \"r\")\n        for Line in TheFile:\n            F = Line.strip().split(\",\")\n            AllCharacters.append(Character(F[0], F[1], F[2], F[3], F[4]))\n        TheFile.close()\n    except:\n        print(\"The file Characters.txt could not be opened or read\")\n    return AllCharacters\n\ndef OutputCharacters(TheCharacters):\n    for C in TheCharacters:\n        print(\"Name:\", C.GetCharacterName(), \"Colour:\", C.GetColour(), \"Super strength:\", C.GetSuperStrength(),\n              \"Fly:\", C.GetFly(), \"Invisible:\", C.GetInvisible())\n\nCharacterOptions = ReadData()\nOutputCharacters(CharacterOptions)\n\nprint(\"Choose two criteria: 1 colour, 2 super strength, 3 fly, 4 invisible\")\nfor Choice in range(2):\n    Criterion = int(input(\"Criterion number \" + str(Choice + 1) + \": \"))\n    if Criterion == 1:\n        Value = input(\"Which colour? \")\n    else:\n        Value = input(\"Yes or No? \")\n    Matches = []\n    for C in CharacterOptions:\n        if Criterion == 1 and C.GetColour() == Value:\n            Matches.append(C)\n        elif Criterion == 2 and C.GetSuperStrength() == Value:\n            Matches.append(C)\n        elif Criterion == 3 and C.GetFly() == Value:\n            Matches.append(C)\n        elif Criterion == 4 and C.GetInvisible() == Value:\n            Matches.append(C)\n    CharacterOptions = Matches          # the second pass only searches the first pass's matches\nprint(\"Number of characters that meet both criteria:\", len(CharacterOptions))\nOutputCharacters(CharacterOptions)",
